 static final String BIZ="ENFPERS20261007_BIZ",AUTH="ENFPERS20261007_AUTH";static final ObjectMapper JSON=new ObjectMapper().findAndRegisterModules();
 static String url;static Path repo,evidence,files;static final List<String> OLD=List.of("CONPROD","CONAUTH","ENFPROD","ENFAUTH","ADJPROD","ADJAUTH","SRCMAIN","SRCAUTH","ENFREG20261007","ENFGREG_BIZ","ENFGREG_AUTH");
 static Map<String,Object> report=new LinkedHashMap<>();static List<Map<String,Object>> checks=new ArrayList<>();
