  int code=0;try{DriverManager.setLoginTimeout(3);try(var admin=DriverManager.getConnection(url,"SYSDBA",required("ENFP_ADMIN_PASSWORD"))){if(phase.equals("preflight-source")||phase.equals("preflight-target")){checkUsersAbsent(admin);report.put("protected",protectedInventory(admin));}else if((phase.equals("initialize")||phase.equals("initialize-continued"))){if(phase.equals("initialize"))checkUsersAbsent(admin);initialize(admin,phase.equals("initialize-continued"));}else if(phase.equals("protected-source-final")||phase.equals("protected-target-final")){var now=protectedInventory(admin);String baseline=phase.contains("source")?"preflight-source-result.json":"preflight-target-result.json";check(JSON.valueToTree(now).equals(JSON.readTree(evidence.resolve(baseline).toFile()).path("protected")),"original engineering identity/source/table bytes unchanged");report.put("protected",now);}else if(phase.equals("verify-restart")||phase.equals("verify-restored")){verify(admin,phase.equals("verify-restored"));}else throw new IllegalArgumentException("Unknown phase");}report.put("failedChecks",0);}catch(Throwable t){code=1;report.put("failedChecks",1);report.put("failureClass",t.getClass().getName());report.put("failureMessage",String.valueOf(t.getMessage()));t.printStackTrace(System.err);}report.put("finishedAt",Instant.now().toString());JSON.writerWithDefaultPrettyPrinter().writeValue(out.toFile(),report);System.out.println("ENF_PERSISTENT_PHASE="+phase+" CHECKS="+checks.size()+" EXIT="+code);System.exit(code);
